WITH web_monthly AS ( SELECT ws.ws_web_site_sk, ws_site.web_name, d.d_year, d.d_month_seq, DATE_TRUNC('month', d.d_date) AS month_start, SUM(ws.ws_ext_sales_price) AS total_sales, AVG(ws.ws_ext_discount_amt / NULLIF(ws.ws_ext_sales_price, 0)) AS avg_discount_rate, MAX(ws.ws_ext_discount_amt) AS max_discount_amount FROM web_sales ws JOIN web_site ws_site ON ws.ws_web_site_sk = ws_site.web_site_sk JOIN date_dim d ON ws.ws_sold_date_sk = d.d_date_sk WHERE ws_site.web_open_date_sk IS NOT NULL AND ws_site.web_open_date_sk <= d.d_date_sk AND (ws_site.web_close_date_sk IS NULL OR ws_site.web_close_date_sk >= d.d_date_sk) GROUP BY ws.ws_web_site_sk, ws_site.web_name, d.d_year, d.d_month_seq, DATE_TRUNC('month', d.d_date) ) SELECT web_name, month_start, total_sales, avg_discount_rate, CASE WHEN avg_discount_rate > 0.2 THEN 'High Discount' WHEN avg_discount_rate > 0.1 THEN 'Medium Discount' ELSE 'Low Discount' END AS discount_category, DENSE_RANK() OVER (PARTITION BY month_start ORDER BY avg_discount_rate DESC) AS discount_rank, max_discount_amount FROM web_monthly ORDER BY month_start DESC, discount_rank
